  font-size: var(--typography-microcopy-xs-strong-font-size);
  font-weight: var(--typography-microcopy-xs-strong-font-weight);
  line-height: var(--typography-microcopy-xs-strong-line-height);
  letter-spacing: var(--typography-microcopy-xs-strong-letter-spacing);
}
.typography-title-sm-strong {
  font-family: var(--typography-title-sm-strong-font-family);
  font-size: var(--typography-title-sm-strong-font-size);
  font-weight: var(--typography-title-sm-strong-font-weight);
  line-height: var(--typography-title-sm-strong-line-height);
  letter-spacing: var(--typography-title-sm-strong-letter-spacing);
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  border: 0;
  overflow: hidden;
  white-space: nowrap;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
}
.bcn-search-trigger .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-help-bar__tooltip .esa-button__label {
  line-height: 0;
  display: inline-flex;
}
.bcn-aldo-msg__tools .esa-button__native:hover:not(:disabled) {
  color: var(--bcn-aldo-600);
}
.bcn-aldo-needs__head .esa-badge {
  font-variant-numeric: tabular-nums;
}
.bcn-aldo-composer__send[data-empty] .esa-button__native {
  cursor: not-allowed;
}
.bcn-admin-btn,
.bcn-admin-btn .esa-button {
  display: inline-flex;
}
.bcn-admin-btn .esa-button__native {
  --focus-ring-color: #fff;
  border-radius: var(--radius-full);
  color: #ffffffb8;
  block-size: 22px;
  min-block-size: 0;
  inline-size: 22px;
  min-inline-size: 0;
  padding: 0;
}
.bcn-admin-btn .esa-button__native:hover,
.bcn-admin-btn .esa-button__native:focus-visible {
  color: #fff;
  background: #ffffff24;
}
.bcn-admin-btn .esa-icon {
  block-size: 14px;
  inline-size: 14px;
}
.bcn-gd__label .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-gd-row .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-disclosure .esa-icon {
  transition: transform 0.15s;
}
.bcn-disclosure[aria-expanded="false"] .esa-icon {
  transform: rotate(-90deg);
}
@media (prefers-reduced-motion: reduce) {
  .bcn-disclosure .esa-icon {
    transition: none;
  }
}
.bcn-countchip__num .esa-badge {
  --badge-radius: var(--radius-full);
  --badge-bg: var(--color-border-default);
  --badge-text-color: var(--color-content-default-secondary);
  box-sizing: border-box;
  font-variant-numeric: tabular-nums;
  min-width: 19px;
  height: 19px;
  box-shadow: 0 0 0 1.5px var(--color-background-elevation-raised);
  justify-content: center;
  align-items: center;
  padding: 0 4px;
  font-size: 0.8125rem;
  line-height: 1;
  display: inline-flex;
}
.bcn-ev-staging__title .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-ev-staging__item .esa-card {
  overflow: visible;
}
.bcn-ev-targets__title .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-ev-targets__item[data-receiving] .esa-card {
  border-color: var(--color-background-brand-muted);
  background: color-mix(in srgb, var(--color-background-brand-muted) 5%, transparent);
}
.bcn-ev-targets__item[data-blocked] .esa-card {
  opacity: 0.45;
}
.bcn-ev-attached__mark .esa-badge {
  --badge-bg: var(--color-background-utility-info-subtle);
  --badge-text-color: var(--color-content-default);
  border: 1px solid color-mix(in srgb, var(--color-background-utility-info) 35%, transparent);
  font-weight: var(--typography-font-weight-medium);
}
.bcn-ev-targets__item .esa-card {
  overflow: visible;
}
.bcn-ev-row__mark .esa-badge {
  --badge-bg: var(--color-background-utility-info-subtle);
  --badge-text-color: var(--color-content-default);
  border: 1px solid color-mix(in srgb, var(--color-background-utility-info) 35%, transparent);
  font-weight: var(--typography-font-weight-medium);
}
.bcn-ev-row__tags .esa-badge {
  --badge-bg: var(--bcn-gray-100);
  --badge-text-color: var(--bcn-gray-700);
  font-weight: var(--typography-font-weight-medium);
}
.user-panel__item .esa-icon {
  color: var(--bcn-gray-500);
}
.user-panel__item--danger .esa-icon {
  color: var(--color-background-utility-danger);
}
.project-switcher__trigger > .esa-icon:first-child {
  color: var(--bcn-gray-500);
  flex-shrink: 0;
}
.nav-section__header:hover .esa-icon,
.nav-section--active .nav-section__header,
.nav-section--active .nav-section__header .esa-icon {
  color: var(--color-background-brand);
}
.nav-section__header > .esa-icon:first-child {
  color: var(--bcn-gray-950);
  flex-shrink: 0;
  transition: color 0.15s;
}
.nav-section__header > .esa-icon:last-child {
  color: var(--bcn-gray-400);
  flex-shrink: 0;
  transition:
    transform 0.15s,
    opacity 0.2s ease-in-out;
}
.nav-section--collapsed .nav-section__header > .esa-icon:last-child {
  transform: rotate(-90deg);
}
.side-nav.collapsed .nav-section__title,
.side-nav.collapsed .nav-section__header > .esa-icon:last-child {
  display: none;
}
.bcn-detail-facts {
  grid-template-columns: minmax(0, 1fr);
  margin: 0;
  display: grid;
}
.bcn-detail-facts > .bcn-detail-fact + .bcn-detail-fact {
  border-top: var(--border-width-default, 1px) solid var(--color-border-default-subtle);
}
@media (width>=48rem) {
  .bcn-detail-facts[data-columns="2"] {
    column-gap: var(--spacing-600, 2rem);
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (width>=48rem) {
  .bcn-detail-facts[data-columns="2"] > .bcn-detail-fact:nth-child(2) {
    border-top: none;
  }
}
@media (width>=48rem) {
  .bcn-detail-facts[data-columns="2"] > .bcn-detail-fact[data-full] {
    grid-column: 1/-1;
  }
}
.bcn-detail-fact {
  gap: var(--spacing-100, 0.25rem);
  padding-block: var(--spacing-300, 0.75rem);
  flex-direction: column;
  display: flex;
}
.bcn-detail-fact__label {
  font-size: var(--typography-label-md-font-size);
  color: var(--color-content-default-secondary);
}
.bcn-detail-fact__value {
  font-size: var(--typography-body-md-font-size, 1rem);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  overflow-wrap: anywhere;
  margin: 0;
}
.bcn-detail-fact__note {
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-font-weight-regular, 400);
  color: var(--color-content-default-secondary);
  font-style: italic;
  display: block;
}
.bcn-tracked-field {
  gap: var(--spacing-050, 0.125rem);
  flex-direction: column;
  min-width: 0;
  display: flex;
}
.bcn-tracked-field [hidden] {
  display: none;
}
.bcn-tracked-field[data-layout="fact"] .bcn-tracked-field__value {
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.bcn-tracked-field__value {
  overflow-wrap: anywhere;
  min-width: 0;
}
.bcn-tracked-field[data-layout="block"] .bcn-tracked-field__read {
  align-items: start;
  column-gap: var(--spacing-200, 0.5rem);
  grid-template-columns: minmax(0, 1fr) auto;
  display: grid;
}
.bcn-tracked-field[data-layout="block"] .bcn-tracked-field__value {
  color: var(--color-content-default);
  margin: 0;
}
.bcn-tracked-field[data-layout="inline"] {
  align-items: center;
  column-gap: var(--spacing-100, 0.25rem);
  vertical-align: middle;
  flex-flow: wrap;
  display: inline-flex;
}
.bcn-tracked-field[data-layout="inline"][data-editing] {
  flex-direction: column;
  align-items: stretch;
  width: 100%;
  display: flex;
}
.bcn-tracked-field__aside {
  flex-wrap: nowrap;
}
.bcn-tracked-field[data-layout="inline"] {
  border-radius: var(--radius-sm);
  position: relative;
}
.bcn-tracked-field[data-layout="inline"]:not([data-editing]) {
  place-self: flex-start start;
}
.bcn-tracked-field[data-layout="inline"]:not([data-editing]) .bcn-tracked-field__read {
  flex-wrap: nowrap;
}
.bcn-tracked-field[data-layout="inline"]:not([data-editing]) [data-tf-edit] {
  aspect-ratio: auto;
  opacity: 0;
  block-size: auto;
  min-block-size: 0;
  inline-size: auto;
  min-inline-size: 0;
  position: absolute;
  inset: 0;
}
.bcn-tracked-field[data-layout="inline"]:not([data-editing]):hover {
  background: var(--color-background-default-hover);
